function validPromotion(p,price){if(!p)return null;if(!Number.isInteger(p.cents)||p.cents<0||p.cents>=Math.round(price*100)||!Number.isFinite(Date.parse(p.start))||!Number.isFinite(Date.parse(p.end))||Date.parse(p.start)>=Date.parse(p.end))return null;return {cents:p.cents,start:String(p.start).slice(0,40),end:String(p.end).slice(0,40)}}
