  if(!validBrandImage(data.negocio.logo)||!validBrandImage(data.negocio.portada))return result({error:'Vuelve a subir el logo o la portada desde el panel.'},400);
  const clean={negocio:{nombre:cleanText(data.negocio.nombre,100),subtitulo:cleanText(data.negocio.subtitulo,150),ubicacion:cleanText(data.negocio.ubicacion,200),whatsapp:phone,logo:cleanText(data.negocio.logo,120),portada:cleanText(data.negocio.portada,120),abierto:data.negocio.abierto!==false},categorias:categories,productos:products};
